package com.zc.agent.core.modules.tool.service;
import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.ObjectMapper;import com.zc.agent.core.modules.runtime.model.ExecutionContext;import com.zc.agent.core.modules.tool.model.*;import com.zc.agent.core.modules.tool.repository.ToolInputObservationRepository;import org.springframework.stereotype.Component;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;
/** 统一记录 Tool 输入契约命中、裁剪、脱敏路径和执行结果，不保存原始敏感载荷。 */
@Component public class ToolInputGovernanceHook implements ToolInvocationHook{
 private final ToolInputObservationRepository repo;private final ObjectMapper mapper;private final ThreadLocal<State> state=new ThreadLocal<>();public ToolInputGovernanceHook(ToolInputObservationRepository repo,ObjectMapper mapper){this.repo=repo;this.mapper=mapper;}
 public void beforeInvoke(ExecutionContext c,RegistryAgentTool t,ToolInvocationRequest r){String raw=r.toolInputText()==null?"":r.toolInputText();String args=json(r.arguments());state.set(new State(System.nanoTime(),raw.length(),args.length(),hash(raw+"\n"+args),sensitive(t)));}
 public void afterInvoke(ExecutionContext c,RegistryAgentTool t,ToolInvocationRequest r,ToolExecutionResult result){save(c,t,"success",null,true);}
 public void onError(ExecutionContext c,RegistryAgentTool t,ToolInvocationRequest r,ToolExecutionException e){save(c,t,"failed",e.errorCode(),!"TOOL_INPUT_SCHEMA_INVALID".equals(e.errorCode()));}
 private void save(ExecutionContext c,RegistryAgentTool t,String status,String error,boolean valid){State s=state.get();state.remove();if(s==null)s=new State(System.nanoTime(),0,0,"",List.of());repo.insert(t.toolCode(),text(t.metadata(),"contractVersion","unversioned"),t.providerType(),t.transportType(),c.currentUser().userId(),c.agentContext().agentId(),c.conversationContext().conversationId(),c.taskContext().taskId(),s.rawChars(),s.finalChars(),s.hash(),valid,s.finalChars()<s.rawChars(),json(s.masked()),status,error,java.util.concurrent.TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-s.started()),"{}");}
 private List<String>sensitive(RegistryAgentTool t){JsonNode n=t.metadata()==null?null:t.metadata().path("inputContract").path("sensitivePaths");if(n==null||!n.isArray())return List.of();List<String>v=new ArrayList<>();n.forEach(x->v.add(x.asText()));return v;}
 private String text(JsonNode n,String key,String fallback){return n!=null&&n.hasNonNull(key)?n.path(key).asText(fallback):fallback;}private String json(Object v){try{return mapper.writeValueAsString(v);}catch(Exception e){return "{}";}}private String hash(String v){try{return java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){return "";}}
 private record State(long started,int rawChars,int finalChars,String hash,List<String>masked){}
}
